 [Authorize(Roles=Roles.Admin)] public async Task<IActionResult> Users(){
  var rows=new List<UserAdminRow>();
  foreach(var u in userManager.Users.OrderByDescending(x=>x.CreatedAtUtc).ToList()) rows.Add(new UserAdminRow{Id=u.Id,Name=u.DisplayName,Email=u.Email??"",Department=u.Department,Initials=u.Initials,IsActive=u.IsActive,IsLocked=u.LockoutEnd>DateTimeOffset.UtcNow,LastLoginAtUtc=u.LastLoginAtUtc,Roles=await userManager.GetRolesAsync(u)});
  ViewBag.Roles=roleManager.Roles.Select(x=>x.Name!).ToList(); return View(rows);
 }
 [Authorize(Roles=Roles.Admin),HttpPost,ValidateAntiForgeryToken] public async Task<IActionResult> CreateUser(CreateUserVm vm){
  if(!ModelState.IsValid){TempData["Error"]="اطلاعات کاربر کامل یا معتبر نیست.";return RedirectToAction(nameof(Users));}
  if(await userManager.FindByEmailAsync(vm.Email)!=null){TempData["Error"]="این ایمیل قبلاً ثبت شده است.";return RedirectToAction(nameof(Users));}
  var initials=string.Concat(vm.Name.Split(' ',StringSplitOptions.RemoveEmptyEntries).Take(2).Select(x=>x[0]));
  var u=new ApplicationUser{UserName=vm.Email,Email=vm.Email,EmailConfirmed=true,DisplayName=vm.Name,Department=vm.Department,Initials=initials,IsActive=vm.IsActive};
  var result=await userManager.CreateAsync(u,vm.Password); if(!result.Succeeded){TempData["Error"]=string.Join(" | ",result.Errors.Select(x=>x.Description));return RedirectToAction(nameof(Users));}
  if(await roleManager.RoleExistsAsync(vm.Role)) await userManager.AddToRoleAsync(u,vm.Role); TempData["Success"]="کاربر با موفقیت ایجاد شد.";return RedirectToAction(nameof(Users));
 }
 [Authorize(Roles=Roles.Admin),HttpPost,ValidateAntiForgeryToken] public async Task<IActionResult> UpdateUser(EditUserVm vm){
  var u=await userManager.FindByIdAsync(vm.Id);if(u==null)return NotFound(); if(u.Email=="admin@ashkancrm.local"&&!vm.IsActive){TempData["Error"]="حساب مدیر اصلی قابل غیرفعال‌سازی نیست.";return RedirectToAction(nameof(Users));}
  u.DisplayName=vm.Name;u.Department=vm.Department;u.IsActive=vm.IsActive;u.Initials=string.Concat(vm.Name.Split(' ',StringSplitOptions.RemoveEmptyEntries).Take(2).Select(x=>x[0]));await userManager.UpdateAsync(u);
  var current=await userManager.GetRolesAsync(u);if(current.Count>0)await userManager.RemoveFromRolesAsync(u,current);if(await roleManager.RoleExistsAsync(vm.Role))await userManager.AddToRoleAsync(u,vm.Role);await userManager.UpdateSecurityStampAsync(u);TempData["Success"]="کاربر و سطح دسترسی بروزرسانی شد.";return RedirectToAction(nameof(Users));
 }
 [Authorize(Roles=Roles.Admin),HttpPost,ValidateAntiForgeryToken] public async Task<IActionResult> ResetUserPassword(string id,string newPassword){var u=await userManager.FindByIdAsync(id);if(u==null)return NotFound();var token=await userManager.GeneratePasswordResetTokenAsync(u);var r=await userManager.ResetPasswordAsync(u,token,newPassword);TempData[r.Succeeded?"Success":"Error"]=r.Succeeded?"رمز عبور تغییر کرد.":string.Join(" | ",r.Errors.Select(x=>x.Description));return RedirectToAction(nameof(Users));}
 [Authorize(Roles=Roles.Admin),HttpPost,ValidateAntiForgeryToken] public async Task<IActionResult> UnlockUser(string id){var u=await userManager.FindByIdAsync(id);if(u==null)return NotFound();await userManager.SetLockoutEndDateAsync(u,null);await userManager.ResetAccessFailedCountAsync(u);TempData["Success"]="قفل حساب باز شد.";return RedirectToAction(nameof(Users));}
