 [Authorize(Roles=Roles.Admin+","+Roles.SalesManager)] public async Task<IActionResult> Forecast(){var deals=await db.CrmDeals.AsNoTracking().ToListAsync();var now=DateTime.UtcNow;var targets=await db.CrmSalesTargets.AsNoTracking().Where(x=>x.Year==now.Year&&x.Month==now.Month&&!x.IsDeleted).ToListAsync();ViewBag.Pipeline=deals.Where(x=>x.Stage!="Won"&&x.Stage!="Lost").Sum(x=>x.Value);ViewBag.Weighted=deals.Where(x=>x.Stage!="Won"&&x.Stage!="Lost").Sum(x=>x.Value*x.Probability/100m);ViewBag.Won=deals.Where(x=>x.Stage=="Won").Sum(x=>x.Value);ViewBag.Commit=deals.Where(x=>x.Stage=="Negotiation").Sum(x=>x.Value);ViewBag.Target=targets.Sum(x=>x.TargetAmount);ViewBag.Stretch=targets.Sum(x=>x.StretchAmount);return View("SqlForecast",deals);}
 [Authorize(Roles=Roles.Admin+","+Roles.SalesManager),HttpPost,ValidateAntiForgeryToken] public async Task<IActionResult> SaveSalesTarget(string owner,int year,int month,decimal targetAmount,decimal stretchAmount){var row=await db.CrmSalesTargets.FirstOrDefaultAsync(x=>x.Owner==owner&&x.Year==year&&x.Month==month);if(row==null){row=new SalesTargetEntity{Owner=owner,Year=year,Month=month,CreatedBy=User.Identity?.Name};db.CrmSalesTargets.Add(row);}row.TargetAmount=targetAmount;row.StretchAmount=stretchAmount;row.UpdatedAtUtc=DateTime.UtcNow;row.UpdatedBy=User.Identity?.Name;await db.SaveChangesAsync();await WriteAudit("TargetUpsert","SalesTarget",row.Id.ToString(),owner);return RedirectToAction(nameof(Forecast));}
